import { mkdtempSync, mkdirSync, writeFileSync } from "node:fs";
import { tmpdir } from "node:os";
import path from "node:path";
import { execFileSync } from "node:child_process";
import { sha256Content } from "./lib/index.js";

// build fixture workdir
const root = mkdtempSync(path.join(tmpdir(), "hashcheck-"));
mkdirSync(path.join(root, "sub"), { recursive: true });
writeFileSync(path.join(root, "a b.txt"), "hello world\n", "utf-8");        // space path, LF
writeFileSync(path.join(root, "crlf.txt"), "line1\r\nline2\r\n", "utf-8");  // CRLF text
mkdirSync(path.join(root, "bin"), { recursive: true });
writeFileSync(path.join(root, "bin", "data.bin"), Buffer.from([0x00, 0xff, 0x89, 0x50, 0x0d, 0x0a, 0x1a])); // binary non-utf8
writeFileSync(path.join(root, "sub", "c.txt"), "abc\n", "utf-8");
// paths incl a deleted (nonexistent) file and _review.json
const paths = ["a b.txt", "crlf.txt", "bin/data.bin", "sub/c.txt", "gone.txt", "_review.json"];

const jsSha = sha256Content(root, paths);
console.log("JS_SHA", jsSha);

const py = `import json,sys
sys.path.insert(0, r"D:\\repository\\skills\\dsh\\langgraph-orchestrator")
from src.verify import compute_content_sha
root = r"${root}"
paths = json.loads(sys.argv[1])
p, sha = compute_content_sha(root, paths)
print("PY_PATHS", json.dumps(p))
print("PY_SHA", sha)
`;
const out = execFileSync("python", ["-c", py, JSON.stringify(paths)], { encoding: "utf-8" });
console.log(out.trim());
const pySha = /PY_SHA\s+(\w+)/.exec(out)[1];
const pyPaths = JSON.parse(/PY_PATHS\s+(.+)/.exec(out)[1]);
console.log("\nMATCH", jsSha === pySha ? "OK ✅" : "MISMATCH ❌");
if (jsSha !== pySha) {
  console.log("js  =", jsSha);
  console.log("py  =", pySha);
  console.log("pyPaths(filtered+sorted) =", JSON.stringify(pyPaths));
  process.exit(2);
}

